import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            s = next(iterator)
        except StopIteration:
            break

        target = sorted(s)

        mismatches = 0
        for i in range(n):
            if s[i] != target[i]:
                mismatches += 1

        results.append(str(mismatches))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
